const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const sender = typeof j.from === 'string' ? j.from : JSON.stringify(j.from || '?');
  const subject = j.subject || '(no subject)';
  const body = (j.textPlain || j.textHtml || '').replace(/<[^>]+>/g, ' ').slice(0, 1500);
  const msgId = j.messageId || (j.metadata && (j.metadata['message-id'] || j.metadata['Message-ID'])) || (sender + '|' + subject + '|' + (j.date || ''));
  out.push({ json: { sender, subject, body, message_id: String(msgId).slice(0, 500) } });
}
return out;

const rows = $input.all().filter(i => i.json && Object.keys(i.json).length && i.json['?column?']);
if (rows.length) return [];
return [{ json: $('Prep').first().json }];

const src = $('Only New').first().json;
let c = { category: 'other', importance: 'normal', summary: src.subject };
try {
  const r = JSON.parse($json.response);
  if (['urgent','job','finance','personal','orders','newsletter','other'].includes(r.category)) c.category = r.category;
  if (['high','normal','low'].includes(r.importance)) c.importance = r.importance;
  if (typeof r.summary === 'string' && r.summary.length > 2) c.summary = r.summary.slice(0, 200);
} catch (e) {}
return [{ json: { ...src, ...c } }];

const j = $('Parse').first().json;
if (j.importance !== 'high' && j.category !== 'urgent') return [];
const icons = {urgent:'🚨',job:'💼',finance:'💶',personal:'💬',orders:'📦',newsletter:'📰',other:'✉️'};
return [{ json: { message: (icons[j.category]||'✉️') + ' ' + j.category.toUpperCase() + ' — ' + j.summary + '\n\nFrom: ' + j.sender + '\nSubject: ' + j.subject } }];
